/* ---------- Payroll ---------- */
function flPayroll(body, again) {
  if (flNeedsApi(body)) return;
  const mon = Session.get('flPayMonth') || todayISO().slice(0, 7), S = FL.list('staff').filter(s => s.status === 'Active'), PR = FL.list('payroll').filter(p => p.month === mon), days = new Date(+mon.slice(0, 4), +mon.slice(5, 7), 0).getDate();
  const role = id => FL.find('staff', id)?.role || '', sum = f => PR.reduce((s, p) => s + (+f(p) || 0), 0), crew = ['Driver', 'Conductor', 'Cleaner'];
  body.innerHTML = `<div style="display:flex;gap:10px;align-items:end;flex-wrap:wrap;margin-bottom:12px"><label class="field"><span>Month</span><input class="input" type="month" id="fp-mon" value="${mon}"></label><button class="btn btn-primary" id="fp-gen">${PR.length ? 'Recalculate from duties' : 'Generate payroll'}</button></div>
    <div class="kpis" style="margin-bottom:14px">${kpi('Staff on payroll', PR.length)}${kpi('Drivers', inr(sum(p => role(p.staffId) === 'Driver' ? p.net : 0)))}${kpi('Cleaners', inr(sum(p => ['Conductor', 'Cleaner'].includes(role(p.staffId)) ? p.net : 0)))}${kpi('Office & others', inr(sum(p => !crew.includes(role(p.staffId)) ? p.net : 0)))}${kpi('Net payable', inr(sum(p => p.net)), `${inr(sum(p => p.status === 'Paid' ? p.net : 0))} paid`)}</div>
    <div class="table-wrap"><table class="table"><thead><tr><th>Staff</th><th>Basis</th><th>Wages</th><th>Bata</th><th>Bonus</th><th>Advance</th><th>Other deductions</th><th>Net pay</th><th>Status</th><th></th></tr></thead><tbody>
    ${PR.sort((a, b) => FL_ROLES.indexOf(role(a.staffId)) - FL_ROLES.indexOf(role(b.staffId))).map(p => `<tr><td><b>${esc(FL.name(p.staffId))}</b><div class="muted small">${esc(role(p.staffId))}</div></td><td>${esc(p.basis)}</td><td>${inr(p.earned)}</td><td>${inr(p.batta)}</td><td>${inr(p.bonus)}</td><td>${inr(p.advance)}</td><td>${inr(p.deduction)}</td><td><b>${inr(p.net)}</b></td><td><span class="chip ${p.status === 'Paid' ? 'green' : 'warn'}">${p.status}</span></td><td class="row-actions">${p.status === 'Paid' ? '' : `<button class="btn btn-sm btn-ghost" data-adj="${p.id}">Adjust</button><button class="btn btn-sm btn-green" data-pay="${p.id}">Pay</button>`}<button class="btn btn-sm btn-ghost" data-slip="${p.id}">Payslip</button></td></tr>`).join('') || '<tr><td class="empty" colspan="10">No payroll for this month yet. Click “Generate payroll”.</td></tr>'}</tbody></table></div>
    <p class="muted small" style="margin-top:10px">Drivers and cleaners are paid for each <b>completed</b> trip: the wage fixed on that duty (the single-driver wage when a driver went alone) plus any bata not already paid in cash on the trip sheet. Office staff get their monthly salary less unpaid leave days. Advances not yet recovered are deducted and marked recovered when the salary is paid.</p>`;
  $('#fp-mon', body).onchange = e => { Session.set('flPayMonth', e.target.value); again(); };
  $('#fp-gen', body).onclick = () => { const D = FL.list('duties').filter(d => d.date.startsWith(mon) && d.status === 'Completed'), A = FL.list('advances').filter(a => !a.recovered && a.date.slice(0, 7) <= mon); let n = 0;
    S.forEach(s => { const id = `${s.id}_${mon}`, old = FL.find('payroll', id); if (old?.status === 'Paid') return;
      const mine = D.filter(d => flCrewIds(d).includes(s.id)).map(d => flPayFor(d, s.id)), lop = old?.lop || 0, bonus = old?.bonus || 0, deduction = old?.deduction || 0, solo = mine.filter(x => x.as === 'Driver (single)').length;
      const earned = s.payType === 'Monthly' ? Math.round(s.monthlySalary - s.monthlySalary / days * lop) : mine.reduce((t, x) => t + x.wage, 0), batta = s.payType === 'Monthly' ? 0 : mine.reduce((t, x) => t + Math.max(0, x.batta - x.paid), 0); // bata already paid in cash on the trip is not paid again
      const advance = A.filter(a => a.staffId === s.id).reduce((t, a) => t + a.amount, 0);
      FL.put('payroll', id, { staffId: s.id, month: mon, basis: s.payType === 'Monthly' ? `Monthly ${inr(s.monthlySalary)}${lop ? ` · ${lop} unpaid day(s)` : ''}` : `${mine.length} trip${mine.length === 1 ? '' : 's'}${solo ? ` · ${solo} alone` : ''}`, duties: mine.length, lop, earned, batta, bonus, advance, deduction, net: Math.max(0, earned + batta + bonus - advance - deduction), status: 'Pending' }); n++; });
    toast(`Payroll calculated for ${n} staff`); again(); };
  $$('[data-adj]', body).forEach(b => b.onclick = () => { const p = FL.find('payroll', b.dataset.adj), s = FL.find('staff', p.staffId);
    openModal(`Adjust · ${s.name}`, `<form id="fx" class="form-grid"><label class="field"><span>Bonus / overtime / incentive (₹)</span><input class="input" type="number" name="bonus" min="0" value="${p.bonus}"></label><label class="field"><span>Other deductions: fines, damage, PF (₹)</span><input class="input" type="number" name="ded" min="0" value="${p.deduction}"></label>${s.payType === 'Monthly' ? `<label class="field"><span>Unpaid leave days</span><input class="input" type="number" name="lop" min="0" max="${days}" step="0.5" value="${p.lop || 0}"></label>` : ''}<button class="btn btn-primary full">Save</button></form>`, { onMount: m => $('#fx', m).onsubmit = e => { e.preventDefault(); const t = e.target, bonus = +t.bonus.value, deduction = +t.ded.value, lop = +(t.lop?.value || 0), earned = s.payType === 'Monthly' ? Math.round(s.monthlySalary - s.monthlySalary / days * lop) : p.earned;
      FL.upd('payroll', p.id, { bonus, deduction, lop, earned, basis: s.payType === 'Monthly' ? `Monthly ${inr(s.monthlySalary)}${lop ? ` · ${lop} unpaid day(s)` : ''}` : p.basis, net: Math.max(0, earned + p.batta + bonus - p.advance - deduction) }); closeModal(); again(); } }); });
  $$('[data-pay]', body).forEach(b => b.onclick = () => { const p = FL.find('payroll', b.dataset.pay); FL.upd('payroll', p.id, { status: 'Paid', paidOn: todayISO() }); FL.list('advances').filter(a => a.staffId === p.staffId && !a.recovered && a.date.slice(0, 7) <= mon).forEach(a => FL.upd('advances', a.id, { recovered: true, recoveredIn: mon })); toast(`${inr(p.net)} paid to ${FL.name(p.staffId)}`); again(); });
  $$('[data-slip]', body).forEach(b => b.onclick = () => { const p = FL.find('payroll', b.dataset.slip), s = FL.find('staff', p.staffId), D = FL.list('duties').filter(d => d.date.startsWith(mon) && d.status === 'Completed' && flCrewIds(d).includes(s.id)).sort((a, c) => a.date.localeCompare(c.date));
    openModal(`Payslip · ${s.name}`, `${printBar('payslip')}<div class="print-sheet"><section class="copy"><header><div class="ph-brand"><b>${esc(SITE_CONFIG.name)} · Fleet</b><span>${esc(SITE_CONFIG.address)}</span></div><div class="ph-kind"><b>PAYSLIP</b><span>${new Date(mon + '-01T00:00:00').toLocaleDateString('en-IN', { month: 'long', year: 'numeric' })}</span></div></header>
      <div class="ph-grid"><div><span>Employee</span><b>${esc(s.name)}</b>${esc(s.role)} · ${esc(s.phone)}</div><div><span>Pay basis</span><b>${esc(p.basis)}</b>${s.bank ? 'Bank a/c ' + esc(s.bank) + (s.ifsc ? ' · ' + esc(s.ifsc) : '') : ''}</div></div>
      <table class="ph-table"><tr><th>Earnings</th><th>Amount</th><th>Deductions</th><th>Amount</th></tr><tr><td>${s.payType === 'Monthly' ? 'Salary' : 'Duty wages'}</td><td>${inr(p.earned)}</td><td>Advance recovered</td><td>${inr(p.advance)}</td></tr><tr><td>Trip bata due</td><td>${inr(p.batta)}</td><td>Other deductions</td><td>${inr(p.deduction)}</td></tr><tr><td>Bonus / incentive</td><td>${inr(p.bonus)}</td><td></td><td></td></tr><tr><th>Total earnings</th><th>${inr(p.earned + p.batta + p.bonus)}</th><th>Net pay</th><th>${inr(p.net)}</th></tr></table>
      ${D.length ? `<table class="ph-table"><tr><th>Date</th><th>Vehicle</th><th>Trip</th><th>Km</th><th>Worked as</th><th>Wage</th><th>Bata due</th></tr>${D.map(d => { const x = flPayFor(d, s.id); return `<tr><td>${fmtDate(d.date)}</td><td class="mono">${esc(FL.veh(d.vehicleId)?.regNo || '')}</td><td>${esc(d.from || '')} → ${esc(d.to || d.route || '')}</td><td>${d.endKm > d.startKm ? d.endKm - d.startKm : ''}</td><td>${esc(x.as)}</td><td>${inr(x.wage)}</td><td>${inr(Math.max(0, x.batta - x.paid))}</td></tr>`; }).join('')}</table>` : ''}
      <div class="ph-sign"><div><span>Employee signature</span><i></i></div><div><span>For ${esc(SITE_CONFIG.name)}</span><i></i>${p.status === 'Paid' ? 'Paid on ' + fmtDate(p.paidOn) : 'Authorised signatory'}</div></div></section></div>`, { wide: true }); });
}

/* ---------- Reports: diesel & mileage, vehicle profit, expenses, drivers, trip register ---------- */
const FL_REPORTS = [['diesel', 'Diesel & mileage'], ['vehicle', 'Vehicle income & expenses'], ['expense', 'Expense heads'], ['driver', 'Driver-wise'], ['register', 'Trip register']];
function flReports(body, again) {
  if (flNeedsApi(body)) return;
  const st = Object.assign({ from: todayISO().slice(0, 8) + '01', to: todayISO(), veh: '', kind: 'diesel' }, Session.get('flReport') || {}), V = Store.get('vehicles');
  const D = FL.list('duties').filter(d => d.status !== 'Cancelled' && d.date >= st.from && d.date <= st.to && (!st.veh || d.vehicleId === st.veh)).sort((a, b) => a.date.localeCompare(b.date) || String(a.createdAt).localeCompare(String(b.createdAt)));
  const reg = d => FL.veh(d.vehicleId)?.regNo || '', km = d => d.endKm > d.startKm ? d.endKm - d.startKm : 0, dl = d => +flSheet(d).dieselL || 0, N = n => (Math.round(n * 100) / 100).toLocaleString('en-IN'), mil = (k, l) => k && l ? (k / l).toFixed(2) : '—', drivers = d => [d.driverId, d.driver2Id].filter(Boolean).map(FL.name).join(' & ');
  const group = (rows, keyOf) => { const m = new Map(); rows.forEach(d => [].concat(keyOf(d)).forEach(k => { if (!m.has(k)) m.set(k, []); m.get(k).push(d); })); return [...m]; }, sum = (rows, f) => rows.reduce((s, d) => s + (+f(d) || 0), 0);
  const fuelled = D.filter(d => km(d) && dl(d)), avgOf = rows => { const f = rows.filter(d => km(d) && dl(d)); return sum(f, dl) ? sum(f, km) / sum(f, dl) : 0; };
  const vehAvg = Object.fromEntries(group(fuelled, d => d.vehicleId).map(([id, r]) => [id, avgOf(r)])), low = d => km(d) && dl(d) && vehAvg[d.vehicleId] && r2(km(d) / dl(d)) < vehAvg[d.vehicleId] * 0.9;
  function r2(x) { return Math.round(x * 100) / 100; }
  const maint = Store.get('maintenance').filter(m => m.date >= st.from && m.date <= st.to && (!st.veh || m.vehicleId === st.veh));
  let kpis = '', chart = '', tables = [], note = ''; // tables: [title, head[], rows[][], foot[]]
  if (st.kind === 'diesel') {
    const byV = group(D, d => d.vehicleId).map(([id, r]) => { const f = r.filter(d => km(d) && dl(d)), ms = f.map(d => km(d) / dl(d)); return { id, reg: FL.veh(id)?.regNo || '', trips: r.length, km: sum(r, km), dl: sum(r, dl), ad: sum(r, d => flSheet(d).adblue), avg: avgOf(r), best: ms.length ? Math.max(...ms) : 0, worst: ms.length ? Math.min(...ms) : 0, low: r.filter(low).length }; }).sort((a, b) => b.avg - a.avg);
    kpis = kpi('Trips', D.length, `${D.length - fuelled.length} without km or diesel`) + kpi('Total km', N(sum(D, km))) + kpi('Diesel filled', N(sum(D, dl)) + ' L') + kpi('Fleet mileage', avgOf(D) ? avgOf(D).toFixed(2) + ' km/L' : '—') + kpi('Low-mileage trips', D.filter(low).length, 'over 10% below the vehicle average', D.some(low));
    chart = `<div class="card stack"><h4>Mileage by vehicle (km per litre)</h4>${bars(byV.filter(x => x.avg).map(x => [x.reg, r2(x.avg), x.avg.toFixed(2)]))}</div>`;
    tables.push(['Vehicle summary', ['Vehicle', 'Trips', 'Km', 'Diesel (L)', 'Mileage', 'Best trip', 'Worst trip', 'Ad-Blue (L)', 'Low trips'], byV.map(x => [x.reg, x.trips, N(x.km), N(x.dl), x.avg ? x.avg.toFixed(2) : '—', x.best ? x.best.toFixed(2) : '—', x.worst ? x.worst.toFixed(2) : '—', N(x.ad), x.low || '']), ['Total', D.length, N(sum(D, km)), N(sum(D, dl)), avgOf(D) ? avgOf(D).toFixed(2) : '—', '', '', N(sum(D, d => flSheet(d).adblue)), D.filter(low).length || '']]);
    tables.push(['Trip-wise diesel and mileage', ['Date', 'Vehicle', 'Trip', 'Drivers', 'Start km', 'Close km', 'Km', 'Diesel (L)', 'Mileage', 'Ad-Blue (L)', 'Remark'], D.map(d => [fmtDate(d.date), reg(d), `${d.from || ''} → ${d.to || ''}`, drivers(d), d.startKm ? N(d.startKm) : '', d.endKm ? N(d.endKm) : '', km(d) ? N(km(d)) : '', dl(d) ? N(dl(d)) : '', mil(km(d), dl(d)), +flSheet(d).adblue ? N(flSheet(d).adblue) : '', low(d) ? 'LOW' : !km(d) ? 'Closing km not entered' : !dl(d) ? 'Diesel not entered' : ''])]);
    note = 'Mileage = total km ÷ diesel litres, taken from each trip sheet. A trip is marked LOW when it is more than 10% below that vehicle’s own average for the period.';
  } else if (st.kind === 'vehicle') {
    const ids = [...new Set([...D.map(d => d.vehicleId), ...maint.map(m => m.vehicleId)])], rows = ids.map(id => { const r = D.filter(d => d.vehicleId === id), done = r.filter(d => d.status === 'Completed'), inc = sum(r, flSheetInc), exp = sum(r, flSheetExp), bata = sum(r, d => ['beta1', 'beta2', 'attBeta'].reduce((s, k) => s + (+flSheet(d)[k] || 0), 0)), crew = sum(done, flDutyTotal) - sum(done, d => flCrewIds(d).reduce((s, i) => { const p = flPayFor(d, i); return s + Math.min(p.batta, p.paid); }, 0)), mt = sum(maint.filter(m => m.vehicleId === id), m => m.cost); return { reg: FL.veh(id)?.regNo || '', trips: r.length, km: sum(r, km), inc, exp, crew, mt, net: inc - exp - crew - mt, bata }; }).sort((a, b) => b.net - a.net), T = f => sum(rows, f);
    kpis = kpi('Income', inr(T(x => x.inc))) + kpi('Trip expenses', inr(T(x => x.exp))) + kpi('Crew wages & bata due', inr(T(x => x.crew))) + kpi('Maintenance', inr(T(x => x.mt))) + kpi('Net', inr(T(x => x.net)), '', T(x => x.net) < 0);
    chart = `<div class="card stack"><h4>Income by vehicle</h4>${bars(rows.filter(x => x.inc).map(x => [x.reg, x.inc, inr(x.inc)]))}</div>`;
    tables.push(['Vehicle income and expenses', ['Vehicle', 'Trips', 'Km', 'Income', 'Trip expenses', 'Crew wages & bata due', 'Maintenance', 'Net', 'Net per km'], rows.map(x => [x.reg, x.trips, N(x.km), inr(x.inc), inr(x.exp), inr(x.crew), inr(x.mt), inr(x.net), x.km ? '₹' + (x.net / x.km).toFixed(2) : '—']), ['Total', T(x => x.trips), N(T(x => x.km)), inr(T(x => x.inc)), inr(T(x => x.exp)), inr(T(x => x.crew)), inr(T(x => x.mt)), inr(T(x => x.net)), T(x => x.km) ? '₹' + (T(x => x.net) / T(x => x.km)).toFixed(2) : '—']]);
    note = 'Trip expenses are the amounts on the trip sheets (including beta paid in cash). Crew wages & bata due are for completed trips, less beta already paid on the trip, so nothing is counted twice. Diesel cost is included only if you enter it under an expense row on the trip sheet.';
  } else if (st.kind === 'expense') {
    const heads = FL_EXPENSES.map(([k, l]) => [l, sum(D, d => flSheet(d)[k])]), tot = sum(D, flSheetExp), used = FL_EXPENSES.filter(([k]) => sum(D, d => flSheet(d)[k]));
    kpis = kpi('Total trip expenses', inr(tot)) + kpi('Advance given', inr(sum(D, d => flSheet(d).advance))) + kpi('Expense per trip', inr(D.length ? tot / D.length : 0)) + kpi('Expense per km', sum(D, km) ? '₹' + (tot / sum(D, km)).toFixed(2) : '—');
    chart = `<div class="card stack"><h4>Where the money went</h4>${bars(heads.filter(h => h[1]).sort((a, b) => b[1] - a[1]).map(h => [h[0], h[1], inr(h[1])]))}</div>`;
    tables.push(['Expense heads', ['Expense', 'Amount', 'Share'], heads.map(h => [h[0], inr(h[1]), tot ? Math.round(h[1] / tot * 100) + '%' : '—']), ['Total', inr(tot), '']]);
    tables.push(['Vehicle-wise expenses', ['Vehicle', ...used.map(u => u[1]), 'Total', 'Advance', 'Balance in hand'], group(D, d => d.vehicleId).map(([id, r]) => [FL.veh(id)?.regNo || '', ...used.map(([k]) => inr(sum(r, d => flSheet(d)[k]))), inr(sum(r, flSheetExp)), inr(sum(r, d => flSheet(d).advance)), inr(sum(r, d => flSheet(d).advance) - sum(r, flSheetExp))])]);
  } else if (st.kind === 'driver') {
    const rows = group(D, d => [d.driverId, d.driver2Id].filter(Boolean)).map(([id, r]) => { const done = r.filter(d => d.status === 'Completed'), pay = done.map(d => flPayFor(d, id)); return { name: FL.name(id), trips: r.length, solo: r.filter(d => !d.driver2Id).length, km: sum(r, km), dl: sum(r, dl), avg: avgOf(r), low: r.filter(low).length, wage: pay.reduce((s, p) => s + p.wage, 0), batta: pay.reduce((s, p) => s + p.batta, 0) }; }).sort((a, b) => b.km - a.km);
    kpis = kpi('Drivers on duty', rows.length) + kpi('Trips', D.length) + kpi('Total km', N(sum(D, km))) + kpi('Wages + bata', inr(sum(rows, x => x.wage + x.batta)));
    chart = `<div class="card stack"><h4>Mileage by driver (km per litre)</h4>${bars(rows.filter(x => x.avg).sort((a, b) => b.avg - a.avg).map(x => [x.name, r2(x.avg), x.avg.toFixed(2)]))}</div>`;
    tables.push(['Driver-wise report', ['Driver', 'Trips', 'Alone', 'Km', 'Diesel (L)', 'Mileage', 'Low trips', 'Wages', 'Bata', 'Total earned'], rows.map(x => [x.name, x.trips, x.solo || '', N(x.km), N(x.dl), x.avg ? x.avg.toFixed(2) : '—', x.low || '', inr(x.wage), inr(x.batta), inr(x.wage + x.batta)])]);
    note = 'When two drivers share a trip, the km and diesel of that trip are shown against both of them. Wages and bata are for completed trips.';
  } else {
    kpis = kpi('Trips', D.length, `${D.filter(d => d.status === 'Completed').length} completed`) + kpi('Total km', N(sum(D, km))) + kpi('Income', inr(sum(D, flSheetInc))) + kpi('Expenses', inr(sum(D, flSheetExp))) + kpi('Income − expenses', inr(sum(D, flSheetInc) - sum(D, flSheetExp)));
    tables.push(['Trip register', ['Date', 'Vehicle', 'Type', 'From', 'To', 'Driver 1', 'Driver 2', 'Attender', 'Start km', 'Close km', 'Km', 'Diesel (L)', 'Mileage', 'Advance', 'Expenses', 'Income', 'Income − expenses', 'Status'], D.map(d => [fmtDate(d.date), reg(d), d.kind || '', d.from || '', d.to || '', FL.name(d.driverId), d.driver2Id ? FL.name(d.driver2Id) : '', flCleaner(d) ? FL.name(flCleaner(d)) : '', d.startKm || '', d.endKm || '', km(d) || '', dl(d) || '', mil(km(d), dl(d)), inr(flSheet(d).advance), inr(flSheetExp(d)), inr(flSheetInc(d)), inr(flSheetInc(d) - flSheetExp(d)), d.status]), ['Total', '', '', '', '', '', '', '', '', '', N(sum(D, km)), N(sum(D, dl)), avgOf(D) ? avgOf(D).toFixed(2) : '—', inr(sum(D, d => flSheet(d).advance)), inr(sum(D, flSheetExp)), inr(sum(D, flSheetInc)), inr(sum(D, flSheetInc) - sum(D, flSheetExp)), '']]);
  }
  const title = FL_REPORTS.find(r => r[0] === st.kind)[1], period = `${fmtDate(st.from)} to ${fmtDate(st.to)}${st.veh ? ' · ' + (FL.veh(st.veh)?.regNo || '') : ''}`;
  const tbl = (t, cls) => `<h4 style="margin:14px 0 8px">${esc(t[0])}</h4><div class="${cls === 'table' ? 'table-wrap' : ''}"><table class="${cls}"><thead><tr>${t[1].map(h => `<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${t[2].map(r => `<tr${r.includes('LOW') ? ' class="row-low"' : ''}>${r.map(c => `<td>${c === 'LOW' ? '<span class="chip warn">Low mileage</span>' : esc(String(c ?? ''))}</td>`).join('')}</tr>`).join('') || `<tr><td class="empty" colspan="${t[1].length}">No trips in this period.</td></tr>`}</tbody>${t[3] && t[2].length ? `<tfoot><tr>${t[3].map(c => `<th>${esc(String(c))}</th>`).join('')}</tr></tfoot>` : ''}</table></div>`;
  body.innerHTML = `<div class="rep-bar"><label class="field"><span>Report</span><select class="input" id="rp-kind">${FL_REPORTS.map(([k, l]) => `<option value="${k}" ${k === st.kind ? 'selected' : ''}>${l}</option>`).join('')}</select></label><label class="field"><span>From</span><input class="input" type="date" id="rp-from" value="${st.from}"></label><label class="field"><span>To</span><input class="input" type="date" id="rp-to" value="${st.to}"></label><label class="field"><span>Vehicle</span><select class="input" id="rp-veh"><option value="">All vehicles</option>${V.map(v => `<option value="${v.id}" ${v.id === st.veh ? 'selected' : ''}>${esc(v.regNo)}</option>`).join('')}</select></label>
      <div class="rep-quick"><button class="btn btn-sm btn-ghost" data-q="today">Today</button><button class="btn btn-sm btn-ghost" data-q="week">Last 7 days</button><button class="btn btn-sm btn-ghost" data-q="month">This month</button><button class="btn btn-sm btn-ghost" data-q="last">Last month</button></div>
      <div class="rep-quick" style="margin-left:auto"><button class="btn btn-outline" id="rp-csv">Download Excel (CSV)</button><button class="btn btn-primary" id="rp-print">Print</button></div></div>
    <div class="kpis" style="margin:14px 0">${kpis}</div>${chart}${tables.map(t => tbl(t, 'table')).join('')}${note ? `<p class="muted small" style="margin-top:10px">${note}</p>` : ''}`;
  const set = p => { Session.set('flReport', Object.assign(st, p)); again(); };
  $('#rp-kind', body).onchange = e => set({ kind: e.target.value }); $('#rp-veh', body).onchange = e => set({ veh: e.target.value });
  $('#rp-from', body).onchange = e => e.target.value && set({ from: e.target.value, to: st.to < e.target.value ? e.target.value : st.to }); $('#rp-to', body).onchange = e => e.target.value && set({ to: e.target.value, from: st.from > e.target.value ? e.target.value : st.from });
  $$('[data-q]', body).forEach(b => b.onclick = () => { const t = todayISO(), q = b.dataset.q, iso = d => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`, n = new Date();
    set(q === 'today' ? { from: t, to: t } : q === 'week' ? { from: todayISO(-6), to: t } : q === 'month' ? { from: t.slice(0, 8) + '01', to: t } : { from: iso(new Date(n.getFullYear(), n.getMonth() - 1, 1)), to: iso(new Date(n.getFullYear(), n.getMonth(), 0)) }); });
  $('#rp-csv', body).onclick = () => { const q = c => { c = String(c ?? '').replace(/₹/g, '').replace(/^—$/, ''); if (/^-?[\d,]+(\.\d+)?$/.test(c)) c = c.replace(/,/g, ''); return /[",\n]/.test(c) ? '"' + c.replace(/"/g, '""') + '"' : c; };
    const csv = '﻿' + [[SITE_CONFIG.name + ' · ' + title], [period], ...tables.flatMap(t => [[], [t[0]], t[1], ...t[2], ...(t[3] && t[2].length ? [t[3]] : [])])].map(r => r.map(q).join(',')).join('\r\n');
    const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })); a.download = `fleet-${st.kind}-${st.from}-to-${st.to}.csv`; document.body.appendChild(a); a.click(); a.remove(); toast('Report downloaded. Open it in Excel.'); };
  $('#rp-print', body).onclick = () => openModal(title, `${printBar('report')}<div class="print-sheet"><section class="copy report-print"><header><div class="ph-brand"><b>${esc(SITE_CONFIG.name)} · Fleet</b><span>${esc(SITE_CONFIG.address)}</span></div><div class="ph-kind"><b>${esc(title.toUpperCase())}</b><span>${esc(period)}</span></div></header>${tables.map(t => tbl(t, 'ph-table')).join('')}${note ? `<p style="font-size:11px;margin-top:8px">${note}</p>` : ''}</section></div>`, { wide: true });
}
